import sys

def max_points(pts):
    n = len(pts)
    if n <= 2:
        return n
    best = 1
    for i in range(n):
        x1, y1 = pts[i]
        for j in range(i + 1, n):
            x2, y2 = pts[j]
            dx, dy = x2 - x1, y2 - y1
            cnt = 0
            for k in range(n):
                x3, y3 = pts[k]
                if dx * (y3 - y1) == dy * (x3 - x1):
                    cnt += 1
            if cnt > best:
                best = cnt
    return best


