import sys
from math import gcd

def max_points(pts):
    n = len(pts)
    if n <= 2:
        return n
    best = 1
    for i in range(n):
        slopes = {}
        x1, y1 = pts[i]
        same = 0
        for j in range(n):
            if i == j:
                continue
            x2, y2 = pts[j]
            dx, dy = x2 - x1, y2 - y1
            if dx == 0 and dy == 0:
                same += 1
                continue
            g = gcd(abs(dx), abs(dy))
            dx //= g
            dy //= g
            if dx < 0 or (dx == 0 and dy < 0):
                dx = -dx
                dy = -dy
            slopes[(dx, dy)] = slopes.get((dx, dy), 0) + 1
        if slopes:
            best = max(best, max(slopes.values()) + 1 + same)
        else:
            best = max(best, 1 + same)
    return best


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    pts = []
    idx = 1
    for _ in range(n):
        pts.append((int(data[idx]), int(data[idx + 1])))
        idx += 2
    print(max_points(pts))
